// Extracted from the complete existing Aurelia v6 treehouse; do not regenerate with a simplified blueprint.
// Source and extraction metadata are included in TREE_META. No database contains these unchanged cells.
// Gzip keeps the complete template small on mobile. Browser and Node use the same decoder.
const packed=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
const TEMPLATE=JSON.parse(await new Response(new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'))).text());

export const TREE_VERSION=TEMPLATE.version;
const {sections:sourceSections,objects:sourceObjects,lifts:sourceLifts,...metadata}=TEMPLATE;
export const TREE_META={...metadata,floors:metadata.levels,objectCount:sourceObjects.length,sectionCount:sourceSections.length};
const sectionIndex=new Map(sourceSections.map(s=>[[s.cx,s.cy,s.cz].join(','),s]));
const byHeight=new Map();
for(const s of sourceSections){let a=byHeight.get(s.cy);if(!a)byHeight.set(s.cy,a=[]);a.push(s);}
const decoded=new Map(),mod=n=>(n%16+16)%16;
function decode(s){
 const key=[s.cx,s.cy,s.cz].join(',');let a=decoded.get(key);if(a)return a;
 a=new Uint8Array(4096);a.fill(255);let offset=0;
 for(let i=0;i<s.runs.length;i+=2){const count=s.runs[i],value=s.runs[i+1];if(value)a.fill(value-1,offset,offset+count);offset+=count;}
 if(offset!==4096)throw Error('Invalid baked treehouse section');decoded.set(key,a);return a;
}
// Undefined means retain the seeded terrain; zero is intentional carved air.
export function baseBlock(x,y,z){
 if(![x,y,z].every(Number.isFinite))return undefined;
 x=Math.floor(x);y=Math.floor(y);z=Math.floor(z);
 const s=sectionIndex.get([Math.floor(x/16),Math.floor(y/16),Math.floor(z/16)].join(','));if(!s)return undefined;
 const value=decode(s)[mod(y)*256+mod(z)*16+mod(x)];return value===255?undefined:value;
}
// Local Y layer, suitable for small incremental original-engine setBlocks batches.
export function layerCells(y){
 if(!Number.isSafeInteger(y))return [];
 const out=[],offset=mod(y)*256;
 for(const s of byHeight.get(Math.floor(y/16))||[]){const a=decode(s);for(let i=0;i<256;i++){const id=a[offset+i];if(id!==255)out.push([s.cx*16+i%16,y,s.cz*16+Math.floor(i/16),id]);}}
 return out;
}
function originOf(d){if(!d||typeof d.uid!=='string'||!Array.isArray(d.origin)||d.origin.length!==3||!d.origin.every(Number.isFinite))throw Error('Invalid treehouse descriptor');return d.origin;}
export function treeEntityUid(descriptor,relativeUid){return descriptor.uid+':'+relativeUid;}
function translatedEntity(source,descriptor,lift=false){
 const o=originOf(descriptor),e=structuredClone(source);e.uid=treeEntityUid(descriptor,source.uid);e.x+=o[0];e.y+=o[1];e.z+=o[2];
 e.building=descriptor.uid;e.structure=descriptor.uid;
 if(lift){e.kind='lift';e.floors=e.floors.map(f=>({...f,y:f.y+o[1]}));if(Number.isFinite(e.destination))e.destination+=o[1];e.boarded=false;return e;}
 e.kind='furniture';e.furnitureType=e.type;e.state={...e.state,building:descriptor.uid};
 for(const key of ['roomFloor','anchorHeight'])if(Number.isFinite(e.state[key]))e.state[key]+=o[1];
 if(e.parent)e.parent=treeEntityUid(descriptor,e.parent);
 if(e.storage){e.slots=e.storage;delete e.storage;}
 return e;
}
export function baseEntities(descriptor){return sourceObjects.map(e=>translatedEntity(e,descriptor)).concat(sourceLifts.map(e=>translatedEntity(e,descriptor,true)));}
export function transformedBuilding(descriptor){
 const o=originOf(descriptor),point=a=>a.map((v,i)=>v+o[i]),uid=descriptor.uid;
 return {uid,kind:'tree',name:TEMPLATE.name,origin:o.slice(),entry:point(TEMPLATE.entry),bounds:TEMPLATE.bounds.map((v,i)=>v+o[i%3]),rooms:TEMPLATE.rooms.map(r=>({...structuredClone(r),x:r.x+o[0],y:r.y+o[1],z:r.z+o[2],door:point(r.door)})),levels:TEMPLATE.levels.map(f=>({...structuredClone(f),y:f.y+o[1]})),landmarks:TEMPLATE.landmarks.map(p=>({...p,x:p.x+o[0],y:p.y+o[1],z:p.z+o[2]})),entities:sourceObjects.map(e=>treeEntityUid(descriptor,e.uid)),lifts:sourceLifts.map(e=>treeEntityUid(descriptor,e.uid)),completed:true,height:TEMPLATE.top,aureliaArchitectureVersion:TREE_VERSION,treehouseRepairVersion:TREE_VERSION,treehouseDefinitiveVersion:TREE_VERSION,dreamEnhanced:TREE_VERSION,aureliaPreserveSnapshot:true,aureliaRoutes:TEMPLATE.routes.map(r=>({...structuredClone(r),y:r.y+o[1],points:r.points.map(point)})),onlineStructure:true};
}
